test('invoice preserves all other fields when adding terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET30',
  });
  const invoice = result.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2024-03-15');
  assert.equal(invoice.status, 'draft');
  assert.ok(Array.isArray(invoice.lines));
  assert.equal(invoice.lines.length, 1);
});

