test('createInvoice with different SKUs and all terms', () => {
  const skus = ['DEV-HOUR', 'LOGO-PACK', 'STICKER'];
  const terms = ['NET14', 'NET30', 'EOM'];

  for (const sku of skus) {
    for (const term of terms) {
      const result = createInvoice({
        customerId: 'C-001',
        issueDate: '2024-03-15',
        lines: [{ sku, qty: 1 }],
        terms: term,
      });
      assert.equal(result.ok, true, `Failed with SKU ${sku} and terms ${term}`);
      assert.equal(result.value.terms, term);
      assert.ok(result.value.dueDate);
    }
  }
});

